// External Dependencies
import React,{ Component } from 'react';

// Internal Dependencies
import './style.css';

class DCS_LogoCarouselItem extends Component {

  static slug = 'divi8_logo_carousel_item';
  render() {
    var prop = this.props;
    var get_description = prop.description; //get the description
    var temp = document.createElement("DIV");
    temp.innerHTML = get_description;
    var defaultimage_url;
    var img_alt;
    if(prop.img !== undefined ){
      defaultimage_url = prop.img;
    }else{
      defaultimage_url = 'data:image/svg+xml;base64,';
    }
    if(prop.img_alt !== undefined){
      img_alt = prop.img_alt;
    }else{
      img_alt = '#';
    }
    //silder all data sent 
    return(
      <div className="carousel_content img_caro">
        <img src={defaultimage_url} alt={img_alt} />          
    </div>
    )
    

  }
}

export default DCS_LogoCarouselItem;
